def find_rectangles(grid, val, rows, cols):
    """Find all rectangular regions of a value"""
    result = []
    visited = set()

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == val and (r, c) not in visited:
                # Expand to find rectangle
                r_min, r_max = r, r
                c_min, c_max = c, c

                # Expand right
                while c_max + 1 < cols and grid[r][c_max + 1] == val:
                    c_max += 1
                # Expand down
                while r_max + 1 < rows and grid[r_max + 1][c_min] == val:
                    r_max += 1

                # Check if this is actually a rectangle
                is_rect = True
                for rr in range(r_min, r_max + 1):
                    for cc in range(c_min, c_max + 1):
                        if grid[rr][cc] != val:
                            is_rect = False
                            break
                    if not is_rect:
                        break

                if is_rect and len(range(r_min, r_max+1)) > 1:
                    visited.add((r, c))
                    result.append({'rows': (r_min, r_max), 'cols': (c_min, c_max)})

    return result

